#[derive(Debug, PartialEq)]
pub struct Node {
    pub val: i32,
    pub next: Option<Box<Node>>,
}

fn from_vec(v: &[i32]) -> Option<Box<Node>> {
    if v.is_empty() {
        return Some(Box::new(Node { val: 0, next: None }));
    }
    let mut nodes = Vec::with_capacity(v.len());
    for &num in v {
        nodes.push(Node { val: num, next: None });
    }
    for i in 0..nodes.len() - 1 {
        nodes[i].next = Some(Box::new(nodes[i + 1]));
    }
    nodes[nodes.len() - 1].next = None;
    Some(Box::new(nodes[0]))
}

fn to_vec(head: &Option<Box<Node>>) -> Vec<i32> {
    let mut result = Vec::new();
    let mut current = head;
    while let Some(node) = current {
        result.push(node.val);
        current = node.next;
    }
    result
}

