pub struct Fib {
    last: u64,
    next: u64,
}

impl Fib {
    pub fn new() -> Fib {
        Fib { last: 0, next: 1 }
    }

    pub fn next(&mut self) -> Option<u64> {
        if self.next > u64::MAX - self.last {
            None
        } else {
            let value = self.last + self.next;
            self.last = self.next;
            self.next = value;
            Some(value)
        }
    }
}

impl Iterator for Fib {
    type Item = u64;

    fn next(&mut self) -> Option<Self::Item> {
        self.next()
    }
}

pub fn fib() -> Fib {
    Fib::new()
}
